import { ObjectPool } from '../../../shared/core/ObjectPool.js';
import { MotionTrails } from '../../../shared/vfx/MotionTrails.js';
import { MathUtils } from '../../../shared/utils/MathUtils.js';

export interface ProjectileConfig {
