import { Vector3 } from 'three';
import type { InstancedMesh } from 'three';
import type { ObjectPool } from '../../../shared/core/ObjectPool.js';
import type { ParticleManager } from '../../../shared/core/ParticleManager.js';
import type { ShockwaveRings } from '../../../shared/vfx/ShockwaveRings.js';
import type { MathUtils } from '../../../shared/utils/MathUtils.js';
import type { NeonMaterials } from '../../../shared/graphics/NeonMaterials.js';
import type { AudioSynth } from '../../../shared/utils/AudioSynth.js';

export interface EnemyConfig {
  row: number;
  col: number;
  position: Vector3;
  materialIndex: number;
}

export class Enemy {
  private mesh: InstancedMesh | null = null;
  private active: boolean = false;
  private row: number = 0;
  private col: number = 0;
  private position: Vector3 = new Vector3();
  private velocity: Vector3 = new Vector3();
  private hitStopTimer: number = 0;
  private hitStopDuration: number = 0.15;

  constructor(
    private pool: ObjectPool<Enemy>,
    private particleManager: ParticleManager,
    private shockwaveRings: ShockwaveRings,
    private materials: NeonMaterials,
    private audioSynth: AudioSynth,
    private mathUtils: MathUtils
  ) {}

  init(index: number, config: EnemyConfig): void {
    this.row = config.row;
    this.col = config.col;
    this.position.copy(config.position);

    // Create mesh if not exists (handled by pool)
    if (!this.mesh) {
      this.mesh = new InstancedMesh(
        this.mathUtils.createAlienGeometry(this.row),
        [this.materials.getEnemyMaterial(this.row)],
        1
      );
      this.mesh.instanceMatrix.setUsage(3); // Dynamic draw usage
    }

    this.active = true;
    this.hitStopTimer = 0;

    // Set initial position
    const matrix = new (require('three').Matrix4)();
    matrix.setPosition(this.position.x, this.position.y, this.position.z);
    this.mesh.setMatrixAt(0, matrix);
    this.mesh.instanceMatrix.needsUpdate = true;
  }

  activate(index: number): void {
    this.active = true;
    this.hitStopTimer = 0;

    const matrix = new (require('three').Matrix4)();
    matrix.setPosition(this.position.x, this.position.y, this.position.z);
    this.mesh?.setMatrixAt(0, matrix);
    this.mesh?.instanceMatrix.needsUpdate = true;
  }

  deactivate(): void {
    this.active = false;
    if (this.mesh) {
      const matrix = new (require('three').Matrix4)();
      matrix.setPosition(-9999, -9999, -9999); // Move off-screen
      this.mesh.setMatrixAt(0, matrix);
      this.mesh.instanceMatrix.needsUpdate = true;
    }
  }

  update(deltaTime: number, globalSpeed: number, direction: number): void {
    if (!this.active || this.hitStopTimer > 0) return;

    // Apply hit-stop delay
    if (this.hitStopTimer > 0) {
      this.hitStopTimer -= deltaTime;
      return;
    }

    // Horizontal movement
    const moveAmount = globalSpeed * direction * deltaTime;
    this.position.x += moveAmount;

    // Update mesh position
    if (this.mesh) {
      const matrix = new (require('three').Matrix4)();
      matrix.setPosition(this.position.x, this.position.y, this.position.z);
      this.mesh.setMatrixAt(0, matrix);
      this.mesh.instanceMatrix.needsUpdate = true;
    }

    // Animate alien sprite (bobbing motion)
    const time = Date.now() * 0.001;
    const bobAmount = Math.sin(time * 2 + this.row) * 0.3;

    if (this.mesh) {
      const matrix = new (require('three').Matrix4)();
      matrix.setPosition(this.position.x, this.position.y + bobAmount, this.position.z);
      this.mesh.setMatrixAt(0, matrix);
      this.mesh.instanceMatrix.needsUpdate = true;
    }
  }

  triggerHitStop(): void {
    if (!this.active) return;
    this.hitStopTimer = this.hitStopDuration;

    // Play impact sound
    this.audioSynth.playExplosion(this.position, 0.3);
  }

  triggerDeath(explosionPosition: Vector3): void {
    this.deactivate();

    // Spawn particles
    const particleCount = Math.floor(Math.random() * 15) + 20;
    for (let i = 0; i < particleCount; i++) {
      this.particleManager.spawnExplosion(
        explosionPosition.x,
        explosionPosition.y,
        explosionPosition.z,
        this.materials.getEnemyColor(this.row).clone()
      );
    }

    // Spawn shockwave ring
    this.shockwaveRings.spawn(explosionPosition.x, explosionPosition.y, explosionPosition.z);

    // Play death sound
    this.audioSynth.playExplosion(explosionPosition, 0.5);
  }

  getRow(): number {
    return this.row;
  }

  getPosition(): Vector3 {
    return this.position.clone();
  }

  isActive(): boolean {
    return this.active;
  }

  dispose(): void {
    if (this.mesh) {
      this.mesh.dispose();
      this.mesh = null;
    }
  }
}

import * as THREE from 'three';
import { ObjectPool } from '../../../shared/core/ObjectPool.js';
import { Projectile } from './Projectile.js';
import { NeonMaterials } from '../../../../shared/graphics/NeonMaterials.js';
import { MathUtils } from '../../../../shared/utils/MathUtils.js';

export class PlayerShip {
  private mesh: THREE.Mesh;
  private position: THREE.Vector3 = new THREE.Vector3();
  private velocity: number = 0;
  private maxSpeed: number;
  private shootCooldown: number = 0;
  private shootDelay: number;
  private isShielded: boolean = false;
  private shieldTimer: number = 0;
  private shieldMesh: THREE.Mesh | null = null;

  constructor(config: { x: number; y: number; z: number; maxSpeed: number; shootDelay: number }) {
    this.position.set(config.x, config.y, config.z);
    this.maxSpeed = config.maxSpeed;
    this.shootDelay = config.shootDelay;

    // Create player ship geometry (retro-futuristic triangle shape)
    const geometry = new THREE.ConeGeometry(0.8, 2.5, 4);
    geometry.rotateX(Math.PI / 2);
    geometry.rotateY(Math.PI / 4);

    this.mesh = new THREE.Mesh(geometry, NeonMaterials.createPlayerMaterial());
    this.mesh.position.copy(this.position);
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = true;

    // Add engine glow effect
    const engineLight = new THREE.PointLight(0x00ffff, 1, 5);
    engineLight.position.set(0, -1, 0.5);
    this.mesh.add(engineLight);
  }

  get mesh(): THREE.Mesh { return this._mesh; }
  private _mesh: THREE.Mesh;

  set mesh(value: THREE.Mesh) { this._mesh = value; }

  update(deltaTime: number, inputX: number, worldBounds: { minX: number; maxX: number }): void {
    // Movement with clamping
    this.velocity = inputX * this.maxSpeed;
    const newX = this.position.x + this.velocity * deltaTime;

    if (newX >= worldBounds.minX && newX <= worldBounds.maxX) {
      this.position.x = newX;
    }

    // Update mesh position
    this.mesh.position.copy(this.position);

    // Cooldown management
    if (this.shootCooldown > 0) {
      this.shootCooldown -= deltaTime * 1000;
      if (this.shootCooldown < 0) this.shootCooldown = 0;
    }

    // Shield timer
    if (this.isShielded && this.shieldTimer > 0) {
      this.shieldTimer -= deltaTime;
      if (this.shieldTimer <= 0) {
        this.deactivateShield();
      }
    }
  }

  canShoot(): boolean {
    return this.shootCooldown <= 0;
  }

  startCooldown(): void {
    this.shootCooldown = this.shootDelay;
  }

  activateShield(): void {
    if (!this.isShielded) {
      this.isShielded = true;
      this.shieldTimer = 5.0; // 5 seconds shield duration

      // Create shield visual
      const shieldGeo = new THREE.SphereGeometry(1.5, 16, 16);
      const shieldMat = new THREE.MeshBasicMaterial({
        color: 0x00ff00,
        transparent: true,
        opacity: 0.3,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending
      });

      this.shieldMesh = new THREE.Mesh(shieldGeo, shieldMat);
      this.shieldMesh.position.y = 0.5;
      this.mesh.add(this.shieldMesh);
    }
  }

  deactivateShield(): void {
    if (this.isShielded && this.shieldMesh) {
      this.isShielded = false;
      this.mesh.remove(this.shieldMesh);
      this.shieldMesh.geometry.dispose();
      this.shieldMesh.material.dispose();
      this.shieldMesh = null;
    }
  }

  isShieldActive(): boolean {
    return this.isShielded;
  }

  get shieldTimeRemaining(): number {
    return this.isShielded ? Math.max(0, this.shieldTimer) : 0;
  }

  dispose(): void {
    this.mesh.geometry.dispose();
    if (this.mesh.material instanceof THREE.Material) {
      this.mesh.material.dispose();
    } else if (Array.isArray(this.mesh.material)) {
      this.mesh.material.forEach(m => m.dispose());
    }

    if (this.shieldMesh) {
      this.shieldMesh.geometry.dispose();
      this.shieldMesh.material.dispose();
    }
  }

  reset(): void {
    this.position.set(0, -2.5, 0);
    this.mesh.position.copy(this.position);
    this.velocity = 0;
    this.shootCooldown = 0;
    this.deactivateShield();
  }
}

