import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { EffectComposer, RenderPass, UnrealBloomPass, ShaderPass } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { EffectComposer, RenderPass, UnrealBloomPass, ShaderPass } from 'three/addons/postprocessing/EffectComposer.js';

// Re-export for clarity - using standard Three.js imports
export class EffectComposerSetup {
  private composer: any;
  private renderer: any;
  private scene: any;
  private camera: any;
  private bloomPass: any;

  constructor(renderer: any, scene: any, camera: any) {
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;

    // Initialize composer with render pass
    this.composer = new EffectComposer(renderer);
    const renderPass = new RenderPass(scene, camera);
    this.composer.addPass(renderPass);

    // Configure bloom for retro-futurism glow
    this.bloomPass = new UnrealBloomPass(
      new (window as any).Vector2(window.innerWidth, window.innerHeight),
      1.5,   // strength: moderate glow without washing out
      0.4,   // radius: soft bloom spread
      0.85   // threshold: only bright emissive surfaces trigger bloom
    );
    this.composer.addPass(this.bloomPass);

    // Optional color grading for warm retro look
    const colorGradingShader = {
      name: 'ColorGrading',
      uniforms: {
        tDiffuse: { value: null },
        gradeAmount: { value: 0.02 },
        tint: { value: new (window as any).Vector3(1.1, 1.05, 0.9) } // warm tint
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float gradeAmount;
        uniform vec3 tint;
        uniform sampler2D tDiffuse;
        varying vec2 vUv;

        void main() {
          vec4 color = texture2D(tDiffuse, vUv);
          // Apply warm tint with subtle saturation boost
          color.rgb = mix(color.rgb, color.rgb * tint, gradeAmount);
          gl_FragColor = color;
        }
      `
    };

    const colorGradingPass = new ShaderPass(colorGradingShader as any);
    this.composer.addPass(colorGradingPass);
  }

  public render(): void {
    this.composer.render();
  }

  public resize(width: number, height: number): void {
    if (this.bloomPass) {
      this.bloomPass.setSize(width, height);
    }
    // Resize all passes in composer
    for (const pass of this.composer.passes) {
      if ('setSize' in pass && typeof pass.setSize === 'function') {
        pass.setSize(width, height);
      }
    }
  }

  public getComposer(): any {
    return this.composer;
  }

  public setBloomStrength(value: number): void {
    if (this.bloomPass) {
      this.bloomPass.strength = value;
    }
  }

  public setBloomRadius(value: number): void {
    if (this.bloomPass) {
      this.bloomPass.radius = value;
    }
  }

  public setBloomThreshold(value: number): void {
    if (this.bloomPass) {
      this.bloomPass.threshold = value;
    }
  }
}

import { Enemy } from '../entities/Enemy.js';
import { MathUtils } from '../../../shared/utils/MathUtils.js';
import { config } from '../config.js';

export class EnemyFormation {
  private enemies: Enemy[][] = [];
  private rows: number;
  private cols: number;
  private spacingX: number;
  private spacingY: number;

  // Movement state
  private direction: number = 1; // 1 = right, -1 = left
  private speed: number = config.enemyBaseSpeed;
  private dropDistance: number = 0.5;
  private moveTimer: number = 0;
  private moveInterval: number = 1.0; // seconds between moves

  // Formation patterns
  private patternPhase: number = 0;
  private patternSpeed: number = 2.0;

  constructor(rows: number, cols: number) {
    this.rows = rows;
    this.cols = cols;
    this.spacingX = config.enemySpacingX;
    this.spacingY = config.enemySpacingY;

    // Initialize enemy grid
    for (let i = 0; i < rows; i++) {
      this.enemies[i] = [];
      for (let j = 0; j < cols; j++) {
        const position = new THREE.Vector3(
          (j - cols / 2 + 0.5) * this.spacingX,
          config.enemyYOffset + i * this.spacingY,
          0
        );

        // Row-based color variation for retro look
        const rowColors = [0xff00ff, 0x00ffff, 0xffff00, 0xff8800];
        const baseColor = rowColors[i % rowColors.length];

        this.enemies[i][j] = new Enemy(position, i, cols - 1 - i, baseColor);
      }
    }
  }

  update(deltaTime: number): void {
    if (this.enemies.every(row => row.every(e => !e.active))) {
      return; // All enemies destroyed
    }

    this.moveTimer += deltaTime;

    // Move horizontally based on direction
    const moveDistance = this.speed * this.direction * deltaTime;

    let hitEdge = false;
    let leftmostX = Infinity;
    let rightmostX = -Infinity;

    for (let i = 0; i < this.rows; i++) {
      for (let j = 0; j < this.cols; j++) {
        const enemy = this.enemies[i][j];
        if (!enemy.active) continue;

        enemy.mesh.position.x += moveDistance;

        // Track bounds
        leftmostX = Math.min(leftmostX, enemy.mesh.position.x);
        rightmostX = Math.max(rightmostX, enemy.mesh.position.x);

        // Check edge collision
        if (enemy.mesh.position.x < config.screenLeftEdge || 
            enemy.mesh.position.x > config.screenRightEdge) {
          hitEdge = true;
        }
      }
    }

    // Reverse direction and drop down if edge reached
    if (hitEdge || this.moveTimer >= this.moveInterval) {
      this.direction *= -1;

      for (let i = 0; i < this.rows; i++) {
        for (let j = 0; j < this.cols; j++) {
          const enemy = this.enemies[i][j];
          if (!enemy.active) continue;

          enemy.mesh.position.y -= this.dropDistance * Math.sign(this.direction);
        }
      }

      this.moveTimer = 0;
    }

    // Update individual enemy animations and behaviors
    for (let i = 0; i < this.rows; i++) {
      for (let j = 0; j < this.cols; j++) {
        const enemy = this.enemies[i][j];
        if (!enemy.active) continue;

        enemy.update(deltaTime);
      }
    }

    // Update pattern phase for formation morphing
    this.patternPhase += this.patternSpeed * deltaTime;
  }

  getActiveEnemies(): Enemy[] {
    const active: Enemy[] = [];
    for (let i = 0; i < this.rows; i++) {
      for (let j = 0; j < this.cols; j++) {
        const enemy = this.enemies[i][j];
        if (enemy.active) active.push(enemy);
      }
    }
    return active;
  }

  getEnemyCount(): number {
    let count = 0;
    for (let i = 0; i < this.rows; i++) {
      for (let j = 0; j < this.cols; j++) {
        if (this.enemies[i][j].active) count++;
      }
    }
    return count;
  }

  getTotalEnemies(): number {
    return this.rows * this.cols;
  }

  getClosestEnemyToBottom(): Enemy | null {
    let closest: Enemy | null = null;
    let maxY = -Infinity;

    for (let i = 0; i < this.rows; i++) {
      for (let j = 0; j < this.cols; j++) {
        const enemy = this.enemies[i][j];
        if (!enemy.active) continue;

        if (enemy.mesh.position.y > maxY) {
          maxY = enemy.mesh.position.y;
          closest = enemy;
        }
      }
    }

    return closest;
  }

  reset(): void {
    this.direction = 1;
    this.speed = config.enemyBaseSpeed;
    this.moveTimer = 0;

    for (let i = 0; i < this.rows; i++) {
      for (let j = 0; j < this.cols; j++) {
        const position = new THREE.Vector3(
          (j - this.cols / 2 + 0.5) * this.spacingX,
          config.enemyYOffset + i * this.spacingY,
          0
        );

        const rowColors = [0xff00ff, 0x00ffff, 0xffff00, 0xff8800];
        const baseColor = rowColors[i % rowColors.length];

        this.enemies[i][j].reset(position, i, this.cols - 1 - i, baseColor);
      }
    }
  }

  increaseDifficulty(): void {
    this.speed = Math.min(this.speed * 1.1, config.maxEnemySpeed);
    this.moveInterval = Math.max(this.moveInterval * 0.9, 0.3);
  }

  dispose(): void {
    for (let i = 0; i < this.rows; i++) {
      for (let j = 0; j < this.cols; j++) {
        this.enemies[i][j].dispose();
      }
    }
  }
}

