import { CONFIG } from './config.js';

class SpaceInvadersGame {
  private engine: GameEngine;
  private input: InputManager;
  private particles: ParticleManager;
  private memory: MemoryManager;
  private cameraShake: CameraShake;
  private hitStop: HitStop;
  private motionTrails: MotionTrails;
  private shockwaves: ShockwaveManager;
  private floatingText: FloatingText;
  private composerSetup: EffectComposerSetup;
  private audio: AudioSynth;

  // Game entities and systems
  private playerShip!: PlayerShip;
  private enemyFormation!: EnemyFormation;
  private projectiles!: ProjectilePool;
  private powerUps!: PowerUp[];
  private collisionSystem!: CollisionSystem;
  private waveManager!: WaveManager;
  private gameManager!: GameManager;

  // Three.js scene objects
  private scene: THREE.Scene;
  private camera: THREE.PerspectiveCamera;
  private renderer: THREE.WebGLRenderer;
  private stars: THREE.Group | null = null;

  constructor() {
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(
      config.camera.fov,
      window.innerWidth / window.innerHeight,
      config.camera.near,
      config.camera.far
    );

    // Initialize core systems
    this.engine = new GameEngine(this.onUpdate.bind(this), this.onRender.bind(this));
    this.input = new InputManager();
    this.particles = new ParticleManager(config.maxParticles);
    this.memory = new MemoryManager();
    this.cameraShake = new CameraShake(0.5, 2.0);
    this.hitStop = new HitStop(100);
    this.motionTrails = new MotionTrails();
    this.shockwaves = new ShockwaveRings();
    this.floatingText = new FloatingText();

    // Initialize audio system
    this.audio = new AudioSynth();

    // Initialize post-processing
    this.composerSetup = new EffectComposerSetup(
      this.scene,
      this.camera,
      this.memory
    );

    // Initialize game systems
    this.projectiles = new ProjectilePool(config.maxProjectiles, {
      speed: config.projectileSpeed,
      damage: 1,
      trailLength: config.trailLength,
      color: config.playerProjectileColor
    }, this.motionTrails);

    this.powerUps = [];
    this.collisionSystem = new CollisionSystem(this);
    this.waveManager = new WaveManager(this);
    this.gameManager = new GameManager(this);

    // Setup renderer and composer
    this.setupRenderer();
    this.composerSetup.init();

    // Create game world
    this.createWorld();

    // Event listeners
    window.addEventListener('resize', () => this.onResize());
    document.addEventListener('visibilitychange', () => this.onVisibilityChange());
  }

  private setupRenderer(): void {
    this.renderer = new THREE.WebGLRenderer({ 
      antialias: false,
      powerPreference: 'high-performance'
    });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;

    // Append to DOM (game container)
    const gameContainer = document.getElementById('game-container');
    if (gameContainer) {
      gameContainer.appendChild(this.renderer.domElement);
    }

    // Camera position
    this.camera.position.set(0, config.playerY + 5, config.cameraDistance);
    this.camera.lookAt(0, config.playerY, 0);
  }

  private createWorld(): void {
    // Create starfield background
    const stars = BackgroundGen.createStarField(config.starCount, config.parallaxSpeeds);
    this.scene.add(stars);
    this.stars = stars;

    // Create player ship
    this.playerShip = new PlayerShip(
      new THREE.Vector3(0, config.playerY, 0),
      this.audio,
      this.motionTrails
    );
    this.scene.add(this.playerShip.getMesh());

    // Initialize enemy formation
    const alienTextures = AlienSpriteGen.generateAlienTextures();
    this.enemyFormation = new EnemyFormation(
      config.enemyRows,
      config.enemyCols,
      config.enemySpacing,
      alienTextures,
      this.audio
    );

    // Add directional light for shadows and depth
    const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
    this.scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.0);
    dirLight.position.set(5, 10, 7);
    this.scene.add(dirLight);
  }

  private onUpdate(deltaTime: number): void {
    // Apply hit-stop timescale
    const effectiveDelta = deltaTime * this.hitStop.getTimescale();

    // Update input
    this.input.update();

    // Update camera shake
    this.cameraShake.update(effectiveDelta);
    if (this.cameraShake.shouldApply()) {
      const shake = this.cameraShake.getShakeVector();
      this.camera.position.x += shake.x * effectiveDelta;
      this.camera.position.y += shake.y * effectiveDelta;
    }

    // Update player ship
    this.playerShip.update(effectiveDelta, this.input);

    // Check if game should be paused
    if (this.gameManager.isPaused()) {
      return;
    }

    // Update enemy formation
    this.enemyFormation.update(effectiveDelta, this.camera.position);

    // Update projectiles
    this.projectiles.meshes.forEach((proj) => {
      proj.update(effectiveDelta);
    });

    // Update power-ups
    this.powerUps.forEach((powerUp) => {
      powerUp.update(effectiveDelta);
    });

    // Update wave manager (UFO spawning, etc.)
    this.waveManager.update(effectiveDelta);

    // Run collision detection
    this.collisionSystem.checkCollisions();

    // Update particles and VFX
    this.particles.update(effectiveDelta);
    this.motionTrails.update(effectiveDelta);
    this.shockwaves.update(effectiveDelta);
    this.floatingText.update(effectiveDelta);

    // Check game over conditions
    this.gameManager.checkGameState();
  }

  private onRender(): void {
    // Render with post-processing
    this.composerSetup.render();
  }

  public triggerCameraShake(intensity: number): void {
    this.cameraShake.shake(intensity);
  }

  public triggerHitStop(duration: number): void {
    this.hitStop.apply(duration);
  }

  public spawnParticles(position: THREE.Vector3, color: number, count: number): void {
    this.particles.spawnBurst(position, color, count);
  }

  public spawnShockwave(position: THREE.Vector3, radius: number = 1.0): void {
    this.shockwaves.spawn(position, radius);
  }

  public showFloatingText(text: string, position: THREE.Vector3, points: number): void {
    this.floatingText.show(text, position, points);
  }

  private onResize(): void {
    const width = window.innerWidth;
    const height = window.innerHeight;

    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();

    this.renderer.setSize(width, height);
    this.composerSetup.onResize(width, height);
  }

  private onVisibilityChange(): void {
    if (document.hidden) {
      this.engine.pause();
    } else {
      this.engine.resume();
    }
  }

  public getGameManager(): GameManager {
    return this.gameManager;
  }

  public getPlayerShip(): PlayerShip {
    return this.playerShip;
  }

  public getEnemyFormation(): EnemyFormation {
    return this.enemyFormation;
  }

  public getProjectiles(): ProjectilePool {
    return this.projectiles;
  }

  public getPowerUps(): PowerUp[] {
    return this.powerUps;
  }

  public addPowerUp(powerUp: PowerUp): void {
    this.powerUps.push(powerUp);
    this.scene.add(powerUp.getMesh());
  }

  public removePowerUp(powerUp: PowerUp): void {
    const index = this.powerUps.indexOf(powerUp);
    if (index > -1) {
      this.powerUps.splice(index, 1);
      this.scene.remove(powerUp.getMesh());
    }
  }

  public playSound(type: 'laser' | 'explosion' | 'ufo' | 'powerup'): void {
    switch (type) {
      case 'laser':
        this.audio.playLaser();
        break;
      case 'explosion':
        this.audio.playExplosion();
        break;
      case 'ufo':
        this.audio.playUfo();
        break;
      case 'powerup':
        this.audio.playPowerUp();
        break;
    }
  }

  public dispose(): void {
    // Dispose all game objects
    this.playerShip.dispose();
    this.enemyFormation.dispose();
    this.projectiles.dispose();

    this.powerUps.forEach(p => p.dispose());
    this.powerUps = [];

    // Dispose VFX systems
    this.motionTrails.dispose();
    this.shockwaves.dispose();
    this.floatingText.dispose();

    // Dispose audio
    this.audio.dispose();

    // Dispose memory manager (disposes all tracked resources)
    this.memory.disposeAll();

    // Dispose renderer and composer
    if (this.renderer) {
      this.renderer.dispose();
    }

    console.log('Space Invaders game disposed successfully');
  }

  public start(): void {
    this.engine.start();
  }

  public stop(): void {
    this.engine.stop();
  }
}

// Initialize game when DOM is ready
window.addEventListener('DOMContentLoaded', () => {
  const game = new SpaceInvadersGame();

  // Expose to window for debugging (optional)
  (window as any).spaceInvadersGame = game;

  // Start the game loop
  game.start();

  // Handle page unload
  window.addEventListener('beforeunload', () => {
    game.dispose();
  });
});

export default SpaceInvadersGame;

/**
 * FloatingText System - Dynamic 3D/HTML score display with physics
 * Part of the AAA Retro-Futurism VFX suite for Space Invaders
 */

import { Vector3, Vector2 } from 'three';

export interface FloatingTextConfig {
  text: string;
  position: Vector3;
  color?: string;
  fontSize?: number;
  duration?: number; // seconds before fade out
  scale?: number;
  velocityY?: number; // initial upward velocity
}

interface TextElement {
  element: HTMLElement;
  position: Vector3;
  velocity: Vector3;
  opacity: number;
  scale: number;
  age: number;
  duration: number;
}

export class FloatingTextSystem {
  private container: HTMLElement;
  private texts: Map<string, TextElement> = new Map();
  private nextId: number = 0;

  constructor(containerSelector: string) {
    this.container = document.querySelector(containerSelector)!;
    if (!this.container) {
      console.error('FloatingTextSystem: Container not found:', containerSelector);
      throw new Error('Container element not found');
    }
  }

  spawn(config: FloatingTextConfig): string {
    const id = `ft_${this.nextId++}`;

    const textElement = document.createElement('div');
    textElement.id = id;
    textElement.className = 'floating-text';
    textElement.textContent = config.text;
    textElement.style.cssText = `
      position: absolute;
      font-family: 'Courier New', monospace;
      font-weight: bold;
      color: ${config.color || '#00ff88'};
      font-size: ${config.fontSize || 24}px;
      pointer-events: none;
      text-shadow: 0 0 10px rgba(0, 255, 136, 0.8), 
                   0 0 20px rgba(0, 255, 136, 0.4);
      opacity: 1;
      transform-origin: center bottom;
    `;

    this.container.appendChild(textElement);

    const textData: TextElement = {
      element: textElement,
      position: config.position.clone(),
      velocity: new Vector3(0, config.velocityY || 50, 0),
      opacity: 1.0,
      scale: config.scale || 1.0,
      age: 0,
      duration: config.duration || 2.0
    };

    this.texts.set(id, textData);
    return id;
  }

  update(deltaTime: number): void {
    const now = Date.now();
    const deltaSeconds = deltaTime / 1000;

    // Update each floating text element
    for (const [id, data] of this.texts) {
      data.age += deltaSeconds;

      // Apply physics: gravity and velocity
      data.position.add(data.velocity.clone().multiplyScalar(deltaSeconds));
      data.velocity.y -= 980 * deltaSeconds; // Gravity: 980 units/s²

      // Fade out based on age
      const fadeProgress = Math.min(data.age / data.duration, 1.0);
      data.opacity = 1.0 - fadeProgress;

      // Scale down as it rises and fades
      const scaleProgress = Math.min(data.age / (data.duration * 0.7), 1.0);
      const currentScale = data.scale * (1.0 - scaleProgress * 0.3);

      // Update DOM element
      if (data.opacity <= 0) {
        data.element.style.display = 'none';
        this.texts.delete(id);
        continue;
      }

      data.element.style.opacity = String(data.opacity);
      data.element.style.transform = `scale(${currentScale})`;
    }

    // Clean up removed elements from DOM
    const domElementsToRemove: string[] = [];
    for (const [id, data] of this.texts) {
      if (!data.element.isConnected) {
        domElementsToRemove.push(id);
      }
    }
    domElementsToRemove.forEach(id => this.texts.delete(id));
  }

  syncWith3D(camera: any, renderer: any): void {
    for (const [id, data] of this.texts) {
      const element = data.element;

      // Project 3D position to 2D screen space
      const vector = data.position.clone();
      vector.project(camera);

      const x = (vector.x * 0.5 + 0.5) * renderer.domElement.clientWidth;
      const y = (-(vector.y * 0.5 - 0.5)) * renderer.domElement.clientHeight;

      // Only show if in front of camera
      if (vector.z > 1 && vector.z < -1) {
        element.style.display = 'none';
        continue;
      }

      element.style.display = 'block';
      element.style.left = `${x}px`;
      element.style.top = `${y}px`;
    }
  }

  clear(): void {
    for (const [id, data] of this.texts) {
      if (data.element.parentNode) {
        data.element.parentNode.removeChild(data.element);
      }
    }
    this.texts.clear();
  }

  dispose(): void {
    this.clear();
    this.texts = new Map();
  }
}

import { MathUtils } from '../../../shared/utils/MathUtils.js';

export interface Star {
  x: number;
  y: number;
  z: number;
  size: number;
  speed: number;
  opacity: number;
}

export class BackgroundGenerator {
  private stars: Star[] = [];
  private readonly starCount: number;
  private readonly seed: number;

  constructor(starCount: number = 500, seed: number = Math.random() * 1000) {
    this.starCount = starCount;
    this.seed = seed;
    this.generateStars();
  }

  private generateStars(): void {
    const random = MathUtils.seededRandom(this.seed);

    for (let i = 0; i < this.starCount; i++) {
      this.stars.push({
        x: random() * 2 - 1, // Range [-1, 1]
        y: random() * 2 - 1,
        z: random() * 5 + 2, // Depth from 2 to 7
        size: random() * 0.03 + 0.01,
        speed: random() * 0.5 + 0.1,
        opacity: random() * 0.5 + 0.5
      });
    }
  }

  public getStars(): Star[] {
    return this.stars;
  }

  public update(deltaTime: number): void {
    // Animate stars with parallax effect
    const time = Date.now() * 0.001;

    for (let i = 0; i < this.stars.length; i++) {
      const star = this.stars[i];

      // Twinkle effect using sine wave
      star.opacity = 0.5 + 0.5 * Math.sin(time * star.speed + i);

      // Slow drift for dynamic feel
      star.x += Math.cos(time + i) * 0.001;
    }
  }

  public dispose(): void {
    this.stars = [];
  }
}

export class NebulaGenerator {
  private readonly colors: THREE.Color[] = [
    new THREE.Color(0x2a004d), // Deep purple
    new THREE.Color(0x0066cc), // Electric blue
    new THREE.Color(0xff0080)  // Neon pink
  ];

  public generateNebulaMesh(): THREE.Mesh {
    const geometry = new THREE.PlaneGeometry(100, 100);

    // Custom shader for nebula effect
    const vertexShader = `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `;

    const fragmentShader = `
      uniform float time;
      uniform vec3 color1;
      uniform vec3 color2;
      varying vec2 vUv;

      // Simplex noise function
      vec3 permute(vec3 x) { return mod(((x*34.0)+1.0)*x, 289.0); }
      float snoise(vec2 v){
        const vec4 C = vec4(0.211324865405187, 0.366025403784439,
                            -0.577350269189626, 0.024390243902439);
        vec2 i  = floor(v + dot(v, C.yy) );
        vec2 x0 = v -   i + dot(i, C.xx);
        vec2 i1;
        i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
        vec4 x12 = x0.xyxy + C.xxzz;
        x12.xy -= i1;
        i = mod(i, 289.0);
        vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
          + i.x + vec3(0.0, i1.x, 1.0 ));
        vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
        m = m*m ;
        return 42.0 * dot( m*m, vec3( dot(p.x,x0), dot(p.y,x12.xy), dot(p.z,x12.zw) ) );
      }

      void main() {
        vec2 uv = vUv * 3.0;
        float n = snoise(uv + time * 0.1);

        // Mix colors based on noise value
        vec3 color = mix(color1, color2, smoothstep(-1.0, 1.0, n));

        // Add subtle variation
        color += snoise(uv * 5.0 - time * 0.2) * 0.1;

        gl_FragColor = vec4(color, 0.3);
      }
    `;

    const material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        time: { value: 0 },
        color1: { value: this.colors[0] },
        color2: { value: this.colors[1] }
      },
      transparent: true,
      side: THREE.DoubleSide,
      depthWrite: false
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.rotation.x = Math.PI / 2;
    mesh.position.z = -50;

    return mesh;
  }

  public updateShaderTime(mesh: THREE.Mesh, deltaTime: number): void {
    if (mesh.material instanceof THREE.ShaderMaterial) {
      const shaderMaterial = mesh.material as any;
      if (shaderMaterial.uniforms && shaderMaterial.uniforms.time) {
        shaderMaterial.uniforms.time.value += deltaTime;
      }
    }
  }

  public dispose(): void {
    this.colors.forEach(color => color.dispose());
  }
}

import { Texture, CanvasTexture } from 'three';

export class AlienSpriteGenerator {
  private static readonly ALIEN_TYPES = [
    // Type 0: Squid-like (top row)
    {
      name: 'squid',
      draw: (ctx: CanvasRenderingContext2D, width: number, height: number, time: number) => {
        const cx = width / 2;
        const cy = height / 2;

        // Body - main oval shape
        ctx.fillStyle = '#00ff88';
        ctx.beginPath();
        ctx.ellipse(cx, cy, width * 0.35, height * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();

        // Head - top section
        ctx.fillStyle = '#00cc66';
        ctx.beginPath();
        ctx.arc(cx, cy - height * 0.35, width * 0.25, 0, Math.PI * 2);
        ctx.fill();

        // Eyes - animated blinking
        const blinkPhase = Math.sin(time * 10) > 0.8 ? 0 : 1;
        if (blinkPhase === 1) {
          ctx.fillStyle = '#ff0000';
          ctx.beginPath();
          ctx.arc(cx - width * 0.1, cy - height * 0.35, width * 0.08, 0, Math.PI * 2);
          ctx.arc(cx + width * 0.1, cy - height * 0.35, width * 0.08, 0, Math.PI * 2);
          ctx.fill();
        }

        // Antennae - waving motion
        const waveTime = time * 5;
        for (let i = -1; i <= 1; i += 2) {
          ctx.strokeStyle = '#00ff88';
          ctx.lineWidth = width * 0.04;
          ctx.beginPath();
          ctx.moveTo(cx + i * width * 0.2, cy - height * 0.35);
          const tipX = cx + i * (width * 0.2 + Math.sin(waveTime + i) * width * 0.1);
          const tipY = cy - height * 0.5 - Math.cos(waveTime * 2) * height * 0.05;
          ctx.quadraticCurveTo(
            cx + i * width * 0.3,
            cy - height * 0.45,
            tipX,
            tipY
          );
          ctx.stroke();
        }

        // Legs - segmented animation
        const legPhase = Math.floor(time * 8) % 2;
        for (let i = -1; i <= 1; i += 2) {
          ctx.strokeStyle = '#00cc66';
          ctx.lineWidth = width * 0.03;

          // Upper leg segment
          ctx.beginPath();
          ctx.moveTo(cx + i * width * 0.3, cy);
          const kneeX = cx + i * (width * 0.4 + Math.sin(waveTime + i) * width * 0.05);
          const kneeY = cy + height * 0.2;
          ctx.lineTo(kneeX, kneeY);
          ctx.stroke();

          // Lower leg segment
          if (legPhase === 1 && i > 0 || legPhase === 0 && i < 0) {
            ctx.beginPath();
            ctx.moveTo(kneeX, kneeY);
            const footX = cx + i * (width * 0.5 + Math.cos(waveTime * 2) * width * 0.1);
            const footY = cy + height * 0.35;
            ctx.lineTo(footX, footY);
            ctx.stroke();
          }
        }
      }
    },
    // Type 1: Crab-like (middle rows)
    {
      name: 'crab',
      draw: (ctx: CanvasRenderingContext2D, width: number, height: number, time: number) => {
        const cx = width / 2;
        const cy = height / 2;

        // Body - wider oval
        ctx.fillStyle = '#ff6600';
        ctx.beginPath();
        ctx.ellipse(cx, cy, width * 0.4, height * 0.35, 0, 0, Math.PI * 2);
        ctx.fill();

        // Head - top section with eyes
        ctx.fillStyle = '#ff8800';
        ctx.beginPath();
        ctx.arc(cx, cy - height * 0.3, width * 0.35, 0, Math.PI * 2);
        ctx.fill();

        // Eyes - blinking animation
        const blinkPhase = Math.sin(time * 10) > 0.8 ? 0 : 1;
        if (blinkPhase === 1) {
          ctx.fillStyle = '#ffffff';
          ctx.beginPath();
          ctx.arc(cx - width * 0.12, cy - height * 0.3, width * 0.07, 0, Math.PI * 2);
          ctx.arc(cx + width * 0.12, cy - height * 0.3, width * 0.07, 0, Math.PI * 2);
          ctx.fill();

          // Pupils
          ctx.fillStyle = '#000000';
          ctx.beginPath();
          ctx.arc(cx - width * 0.12, cy - height * 0.3, width * 0.03, 0, Math.PI * 2);
          ctx.arc(cx + width * 0.12, cy - height * 0.3, width * 0.03, 0, Math.PI * 2);
          ctx.fill();
        }

        // Claws - animated opening/closing
        const clawPhase = Math.sin(time * 6) > 0 ? 'open' : 'closed';
        for (let i = -1; i <= 1; i += 2) {
          ctx.strokeStyle = '#ffaa00';
          ctx.lineWidth = width * 0.04;

          // Claw arm
          ctx.beginPath();
          ctx.moveTo(cx + i * width * 0.35, cy);

          if (clawPhase === 'open') {
            const elbowX = cx + i * (width * 0.5 + Math.abs(i) * width * 0.1);
            const elbowY = cy - height * 0.1;
            ctx.lineTo(elbowX, elbowY);

            // Claw hand
            ctx.beginPath();
            ctx.moveTo(elbowX, elbowY);
            const handX = cx + i * (width * 0.65 + Math.sin(time * 8) * width * 0.05);
            const handY = cy - height * 0.2;
            ctx.lineTo(handX, handY);
            ctx.stroke();

            // Claw fingers
            ctx.strokeStyle = '#ffcc00';
            ctx.lineWidth = width * 0.02;
            for (let f = -1; f <= 1; f += 2) {
              ctx.beginPath();
              ctx.moveTo(handX, handY + f * height * 0.03);
              ctx.lineTo(handX + i * width * 0.08, handY + f * height * 0.06);
              ctx.stroke();
            }
          } else {
            // Closed claws
            const elbowX = cx + i * (width * 0.45);
            const elbowY = cy - height * 0.15;
            ctx.lineTo(elbowX, elbowY);
            ctx.stroke();

            // Closed claw hand
            ctx.beginPath();
            ctx.moveTo(elbowX, elbowY);
            const handX = cx + i * (width * 0.48);
            const handY = cy - height * 0.2;
            ctx.lineTo(handX, handY);
            ctx.stroke();
          }
        }

        // Legs - multiple segments
        for (let i = -1; i <= 1; i += 2) {
          const legCount = 3;
          for (let j = 0; j < legCount; j++) {
            ctx.strokeStyle = '#ff8800';
            ctx.lineWidth = width * 0.025;

            const baseY = cy + height * 0.1 + j * height * 0.1;
            const kneeX = cx + i * (width * 0.35 + j * width * 0.05);
            const kneeY = cy + height * 0.25 + Math.sin(time * 4 + j) * height * 0.03;

            ctx.beginPath();
            ctx.moveTo(cx + i * width * 0.3, baseY);
            ctx.lineTo(kneeX, kneeY);
            ctx.stroke();
          }
        }
      }
    },
    // Type 2: Octopus-like (bottom rows)
    {
      name: 'octopus',
      draw: (ctx: CanvasRenderingContext2D, width: number, height: number, time: number) => {
        const cx = width / 2;
        const cy = height / 2;

        // Head - rounded top with eyes
        ctx.fillStyle = '#9900ff';
        ctx.beginPath();
        ctx.arc(cx, cy - height * 0.15, width * 0.38, Math.PI, 0);
        ctx.fill();

        // Body - wider bottom section
        ctx.beginPath();
        ctx.moveTo(cx - width * 0.38, cy - height * 0.15);
        ctx.bezierCurveTo(
          cx - width * 0.45, cy + height * 0.2,
          cx + width * 0.45, cy + height * 0.2,
          cx + width * 0.38, cy - height * 0.15
        );
        ctx.fill();

        // Eyes - large and expressive
        const blinkPhase = Math.sin(time * 10) > 0.8 ? 0 : 1;
        if (blinkPhase === 1) {
          ctx.fillStyle = '#ffffff';
          ctx.beginPath();
          ctx.arc(cx - width * 0.12, cy - height * 0.25, width * 0.09, 0, Math.PI * 2);
          ctx.arc(cx + width * 0.12, cy - height * 0.25, width * 0.09, 0, Math.PI * 2);
          ctx.fill();

          // Pupils - tracking animation
          const trackX = Math.sin(time * 3) * width * 0.03;
          ctx.fillStyle = '#000000';
          ctx.beginPath();
          ctx.arc(cx - width * 0.12 + trackX, cy - height * 0.25, width * 0.04, 0, Math.PI * 2);
          ctx.arc(cx + width * 0.12 + trackX, cy - height * 0.25, width * 0.04, 0, Math.PI * 2);
          ctx.fill();
        }

        // Tentacles - flowing motion
        const tentacleCount = 6;
        for (let i = 0; i < tentacleCount; i++) {
          const angleOffset = ((i / tentacleCount) - 0.5) * Math.PI;
          const waveTime = time + i * 0.5;

          ctx.strokeStyle = '#aa00ff';
          ctx.lineWidth = width * 0.03;

          // Start from bottom of head
          const startX = cx + Math.sin(angleOffset) * width * 0.3;
          const startY = cy - height * 0.15;

          ctx.beginPath();
          ctx.moveTo(startX, startY);

          // Tentacle path with wave motion
          let prevX = startX;
          let prevY = startY;

          for (let j = 1; j <= 3; j++) {
            const t = j / 3;
            const tipX = cx + Math.sin(angleOffset + Math.sin(waveTime * 2) * 0.3) * width * (0.35 + t * 0.1);
            const tipY = cy - height * 0.15 + t * height * 0.4 + Math.cos(waveTime * 3) * height * 0.05;

            // Quadratic bezier for smooth curve
            const cpX = (prevX + tipX) / 2;
            const cpY = prevY + (tipY - prevY) * 0.5;

            ctx.quadraticCurveTo(cpX, cpY, tipX, tipY);
            prevX = tipX;
            prevY = tipY;
          }

          ctx.stroke();
        }

        // Mouth - animated expression
        const mouthOpen = Math.abs(Math.sin(time * 5)) > 0.7 ? 1 : 0;
        if (mouthOpen) {
          ctx.fillStyle = '#6600cc';
          ctx.beginPath();
          ctx.ellipse(cx, cy + height * 0.05, width * 0.15, height * 0.08, 0, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
  ];

  static generateAlienTexture(
    alienType: number,
    rowColor: number = 0xffffff,
    time: number = 0
  ): CanvasTexture {
    const width = 64;
    const height = 64;

    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;

    const ctx = canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Failed to get canvas context');
    }

    // Clear background
    ctx.clearRect(0, 0, width, height);

    // Apply row color tint
    const baseColor = new THREE.Color(rowColor);

    // Draw alien based on type
    if (alienType >= 0 && alienType < this.ALIEN_TYPES.length) {
      const alienDef = this.ALIEN_TYPES[alienType];

      // Create gradient for depth effect
      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, `hsl(${baseColor.getHSL().h * 360}, ${baseColor.getHSL().s * 100}%, 70%)`);
      gradient.addColorStop(0.5, `hsl(${baseColor.getHSL().h * 360}, ${baseColor.getHSL().s * 100}%, 50%)`);
      gradient.addColorStop(1, `hsl(${baseColor.getHSL().h * 360}, ${baseColor.getHSL().s * 100}%, 30%)`);

      // Temporarily replace color functions with gradient
      const originalFillStyle = ctx.fillStyle;
      const originalStrokeStyle = ctx.strokeStyle;
      ctx.fillStyle = gradient;
      ctx.strokeStyle = gradient;

      alienDef.draw(ctx, width, height, time);

      ctx.fillStyle = originalFillStyle;
      ctx.strokeStyle = originalStrokeStyle;
    } else {
      // Default alien if type out of range
      ctx.fillStyle = '#00ff88';
      ctx.fillRect(10, 10, 44, 44);
    }

    return new CanvasTexture(canvas);
  }

  static generateAlienSpriteFrames(
    alienType: number,
    rowColor: number = 0xffffff,
    frameCount: number = 2,
    fps: number = 10
  ): CanvasTexture[] {
    const frames: CanvasTexture[] = [];
    const duration = 1 / fps;

    for (let i = 0; i < frameCount; i++) {
      const time = i * duration;
      const texture = this.generateAlienTexture(alienType, rowColor, time);
      frames.push(texture);
    }

    return frames;
  }

  static generatePowerUpIcon(
    powerUpType: 'rapid' | 'spread' | 'shield',
    time: number = 0
  ): CanvasTexture {
    const width = 64;
    const height = 64;

    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;

    const ctx = canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Failed to get canvas context');
    }

    // Clear background with transparency
    ctx.clearRect(0, 0, width, height);

    let color: string;
    let drawFunc: (ctx: CanvasRenderingContext2D, w: number, h: number, t: number) => void;

    switch (powerUpType) {
      case 'rapid':
        color = '#ff0088';
        drawFunc = (ctx, w, h, t) => {
          // Lightning bolt shape
          ctx.fillStyle = color;
          ctx.beginPath();
          ctx.moveTo(w * 0.3, h * 0.2);
          ctx.lineTo(w * 0.5, h * 0.4);
          ctx.lineTo(w * 0.4, h * 0.4);
          ctx.lineTo(w * 0.6, h * 0.7);
          ctx.lineTo(w * 0.3, h * 0.5);
          ctx.lineTo(w * 0.4, h * 0.5);
          ctx.closePath();
          ctx.fill();

          // Glow effect
          ctx.shadowColor = color;
          ctx.shadowBlur = 10;
          ctx.fill();
          ctx.shadowBlur = 0;
        };
        break;

      case 'spread':
        color = '#ffaa00';
        drawFunc = (ctx, w, h, t) => {
          // Three-projectile spread pattern
          for (let i = -1; i <= 1; i++) {
            ctx.fillStyle = color;
            ctx.beginPath();
            const offsetX = w * 0.3 + i * w * 0.2;
            const offsetY = h * 0.5 + Math.sin(t * 5 + i) * h * 0.1;
            ctx.arc(offsetX, offsetY, w * 0.12, 0, Math.PI * 2);
            ctx.fill();

            // Glow effect
            ctx.shadowColor = color;
            ctx.shadowBlur = 8;
            ctx.fill();
            ctx.shadowBlur = 0;
          }
        };
        break;

      case 'shield':
        color = '#00ccff';
        drawFunc = (ctx, w, h, t) => {
          // Shield dome with energy field
          const gradient = ctx.createRadialGradient(
            w * 0.32, h * 0.32, 0,
            w * 0.32, h * 0.32, w * 0.25
          );
          gradient.addColorStop(0, '#ffffff');
          gradient.addColorStop(0.3, color);
          gradient.addColorStop(1, 'transparent');

          ctx.fillStyle = gradient;
          ctx.beginPath();
          ctx.arc(w * 0.32, h * 0.4, w * 0.25, Math.PI, 0);
          ctx.fill();

          // Shield base
          ctx.fillStyle = color;
          ctx.fillRect(w * 0.2, h * 0.6, w * 0.24, h * 0.15);

          // Energy ring rotation
          const rotateAngle = t * Math.PI * 2;
          ctx.save();
          ctx.translate(w * 0.32, h * 0.4);
          ctx.rotate(rotateAngle);
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = w * 0.02;
          ctx.beginPath();
          ctx.arc(0, 0, w * 0.18, 0, Math.PI * 2);
          ctx.stroke();
          ctx.restore();
        };
        break;
    }

    drawFunc(ctx, width, height, time);

    return new CanvasTexture(canvas);
  }

  static generateBackgroundStars(
    starCount: number = 200,
    layerSpeeds: number[] = [0.1, 0.5, 1.0]
  ): THREE.Points[] {
    const stars: THREE.Points[] = [];

    for (let layer = 0; layer < layerSpeeds.length; layer++) {
      const positions = new Float32Array(starCount * 3);
      const colors = new Float32Array(starCount * 3);

      for (let i = 0; i < starCount; i++) {
        const idx = i * 3;

        // Random position in wide area
        positions[idx] = (Math.random() - 0.5) * 100;     // x
        positions[idx + 1] = (Math.random() - 0.5) * 50;  // y
        positions[idx + 2] = (Math.random() - 0.5) * 30;  // z

        // Star color with slight variation
        const brightness = 0.7 + Math.random() * 0.3;
        colors[idx] = brightness;     // r
        colors[idx + 1] = brightness; // g
        colors[idx + 2] = brightness; // b
      }

      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

      const material = new THREE.PointsMaterial({
        size: layerSpeeds[layer] * 0.8,
        vertexColors: true,
        transparent: true,
        opacity: 0.8 - layer * 0.2,
        blending: THREE.AdditiveBlending
      });

      const points = new THREE.Points(geometry, material);
      points.userData.layerSpeed = layerSpeeds[layer];
      stars.push(points);
    }

    return stars;
  }

  static generateStarTwinkleAnimation(
    stars: THREE.Points[],
    deltaTime: number,
    time: number
  ): void {
    stars.forEach((starField, index) => {
      const speed = starField.userData.layerSpeed || 0.5;

      // Apply twinkle effect to opacity based on layer and time
      const baseOpacity = 0.8 - index * 0.2;
      const twinkleFactor = Math.sin(time * speed * 2 + starField.position.x) * 0.3;

      if (starField.material instanceof THREE.PointsMaterial) {
        starField.material.opacity = Math.max(0.3, baseOpacity + twinkleFactor);
      }
    });
  }

  static disposeAllTextures(textures: CanvasTexture[]): void {
    textures.forEach(texture => {
      texture.dispose();
    });
  }
}

import { GameEngine } from '../../shared/core/GameEngine.js';
import { InputManager } from '../../shared/core/InputManager.js';
import { ParticleManager } from '../../shared/core/ParticleManager.js';
import { MemoryManager } from '../../shared/core/MemoryManager.js';
import { CameraShake } from '../../shared/vfx/CameraShake.js';
import { HitStop } from '../../shared/vfx/HitStop.js';
import { MotionTrails } from '../../shared/vfx/MotionTrails.js';
import { ShockwaveManager } from '../../shared/vfx/ShockwaveRings.js';
import { FloatingTextSystem } from '../../shared/vfx/FloatingText.js';
import { EffectComposerSetup } from '../../shared/graphics/EffectComposerSetup.js';
import { AudioSynth } from '../../shared/utils/AudioSynth.js';
import { MathUtils } from '../../shared/utils/MathUtils.js';

import { PlayerShip } from './entities/PlayerShip.js';
import { Enemy } from './entities/Enemy.js';
import { Projectile, ProjectilePool } from './entities/Projectile.js';
import { PowerUp } from './entities/PowerUp.js';

import { GameManager } from './systems/GameManager.js';
import { EnemyFormation } from './systems/EnemyFormation.js';
import { CollisionSystem } from './systems/CollisionSystem.js';
import { WaveManager } from './systems/WaveManager.js';

import { AlienSpriteGenerator } from './assets/AlienSpriteGen.js';
import { BackgroundGenerator } from './assets/BackgroundGen.js';
import { PowerUpIcons } from './assets/PowerUpIcons.js';

import { CONFIG } from './config.js';

class SpaceInvadersGame {
  private engine: GameEngine;
  private input: InputManager;
  private particles: ParticleManager;
  private memory: MemoryManager;
  private cameraShake: CameraShake;
  private hitStop: HitStop;
  private motionTrails: MotionTrails;
  private shockwaves: ShockwaveManager;
  private floatingText: FloatingText;
  private composerSetup: EffectComposerSetup;
  private audio: AudioSynth;

  // Game entities and systems
  private playerShip!: PlayerShip;
  private enemyFormation!: EnemyFormation;
  private projectiles!: ProjectilePool;
  private powerUps!: PowerUp[];
  private collisionSystem!: CollisionSystem;
  private waveManager!: WaveManager;
  private gameManager!: GameManager;

  // Three.js scene objects
  private scene: THREE.Scene;
  private camera: THREE.PerspectiveCamera;
  private renderer: THREE.WebGLRenderer;
  private stars: THREE.Group | null = null;

  constructor() {
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(
      config.camera.fov,
      window.innerWidth / window.innerHeight,
      config.camera.near,
      config.camera.far
    );

    // Initialize core systems
    this.engine = new GameEngine(this.onUpdate.bind(this), this.onRender.bind(this));
    this.input = new InputManager();
    this.particles = new ParticleManager(config.maxParticles);
    this.memory = new MemoryManager();
    this.cameraShake = new CameraShake(0.5, 2.0);
    this.hitStop = new HitStop(100);
    this.motionTrails = new MotionTrails();
    this.shockwaves = new ShockwaveManager();
    this.floatingText = new FloatingText();

    // Initialize audio system
    this.audio = new AudioSynth();

    // Initialize post-processing
    this.composerSetup = new EffectComposerSetup(
      this.scene,
      this.camera,
      this.memory
    );

    // Initialize game systems
    this.projectiles = new ProjectilePool(config.maxProjectiles, {
      speed: config.projectileSpeed,
      damage: 1,
      trailLength: config.trailLength,
      color: config.playerProjectileColor
    }, this.motionTrails);

    this.powerUps = [];
    this.collisionSystem = new CollisionSystem(this);
    this.waveManager = new WaveManager(this);
    this.gameManager = new GameManager(this);

    // Setup renderer and composer
    this.setupRenderer();
    this.composerSetup.init();

    // Create game world
    this.createWorld();

    // Event listeners
    window.addEventListener('resize', () => this.onResize());
    document.addEventListener('visibilitychange', () => this.onVisibilityChange());
  }

  private setupRenderer(): void {
    this.renderer = new THREE.WebGLRenderer({ 
      antialias: false,
      powerPreference: 'high-performance'
    });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;

    // Append to DOM (game container)
    const gameContainer = document.getElementById('game-container');
    if (gameContainer) {
      gameContainer.appendChild(this.renderer.domElement);
    }

    // Camera position
    this.camera.position.set(0, config.playerY + 5, config.cameraDistance);
    this.camera.lookAt(0, config.playerY, 0);
  }

  private createWorld(): void {
    // Create starfield background
    const stars = BackgroundGen.createStarField(config.starCount, config.parallaxSpeeds);
    this.scene.add(stars);
    this.stars = stars;

    // Create player ship
    this.playerShip = new PlayerShip(
      new THREE.Vector3(0, config.playerY, 0),
      this.audio,
      this.motionTrails
    );
    this.scene.add(this.playerShip.getMesh());

    // Initialize enemy formation
    const alienTextures = AlienSpriteGen.generateAlienTextures();
    this.enemyFormation = new EnemyFormation(
      config.enemyRows,
      config.enemyCols,
      config.enemySpacing,
      alienTextures,
      this.audio
    );

    // Add directional light for shadows and depth
    const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
    this.scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.0);
    dirLight.position.set(5, 10, 7);
    this.scene.add(dirLight);
  }

  private onUpdate(deltaTime: number): void {
    // Apply hit-stop timescale
    const effectiveDelta = deltaTime * this.hitStop.getTimescale();

    // Update input
    this.input.update();

    // Update camera shake
    this.cameraShake.update(effectiveDelta);
    if (this.cameraShake.shouldApply()) {
      const shake = this.cameraShake.getShakeVector();
      this.camera.position.x += shake.x * effectiveDelta;
      this.camera.position.y += shake.y * effectiveDelta;
    }

    // Update player ship
    this.playerShip.update(effectiveDelta, this.input);

    // Check if game should be paused
    if (this.gameManager.isPaused()) {
      return;
    }

    // Update enemy formation
    this.enemyFormation.update(effectiveDelta, this.camera.position);

    // Update projectiles
    this.projectiles.meshes.forEach((proj) => {
      proj.update(effectiveDelta);
    });

    // Update power-ups
    this.powerUps.forEach((powerUp) => {
      powerUp.update(effectiveDelta);
    });

    // Update wave manager (UFO spawning, etc.)
    this.waveManager.update(effectiveDelta);

    // Run collision detection
    this.collisionSystem.checkCollisions();

    // Update particles and VFX
    this.particles.update(effectiveDelta);
    this.motionTrails.update(effectiveDelta);
    this.shockwaves.update(effectiveDelta);
    this.floatingText.update(effectiveDelta);

    // Check game over conditions
    this.gameManager.checkGameState();
  }

  private onRender(): void {
    // Render with post-processing
    this.composerSetup.render();
  }

  public triggerCameraShake(intensity: number): void {
    this.cameraShake.shake(intensity);
  }

  public triggerHitStop(duration: number): void {
    this.hitStop.apply(duration);
  }

  public spawnParticles(position: THREE.Vector3, color: number, count: number): void {
    this.particles.spawnBurst(position, color, count);
  }

  public spawnShockwave(position: THREE.Vector3, radius: number = 1.0): void {
    this.shockwaves.spawn(position, radius);
  }

  public showFloatingText(text: string, position: THREE.Vector3, points: number): void {
    this.floatingText.show(text, position, points);
  }

  private onResize(): void {
    const width = window.innerWidth;
    const height = window.innerHeight;

    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();

    this.renderer.setSize(width, height);
    this.composerSetup.onResize(width, height);
  }

  private onVisibilityChange(): void {
    if (document.hidden) {
      this.engine.pause();
    } else {
      this.engine.resume();
    }
  }

  public getGameManager(): GameManager {
    return this.gameManager;
  }

  public getPlayerShip(): PlayerShip {
    return this.playerShip;
  }

  public getEnemyFormation(): EnemyFormation {
    return this.enemyFormation;
  }

  public getProjectiles(): ProjectilePool {
    return this.projectiles;
  }

  public getPowerUps(): PowerUp[] {
    return this.powerUps;
  }

  public addPowerUp(powerUp: PowerUp): void {
    this.powerUps.push(powerUp);
    this.scene.add(powerUp.getMesh());
  }

  public removePowerUp(powerUp: PowerUp): void {
    const index = this.powerUps.indexOf(powerUp);
    if (index > -1) {
      this.powerUps.splice(index, 1);
      this.scene.remove(powerUp.getMesh());
    }
  }

  public playSound(type: 'laser' | 'explosion' | 'ufo' | 'powerup'): void {
    switch (type) {
      case 'laser':
        this.audio.playLaser();
        break;
      case 'explosion':
        this.audio.playExplosion();
        break;
      case 'ufo':
        this.audio.playUfo();
        break;
      case 'powerup':
        this.audio.playPowerUp();
        break;
    }
  }

  public dispose(): void {
    // Dispose all game objects
    this.playerShip.dispose();
    this.enemyFormation.dispose();
    this.projectiles.dispose();

    this.powerUps.forEach(p => p.dispose());
    this.powerUps = [];

    // Dispose VFX systems
    this.motionTrails.dispose();
    this.shockwaves.dispose();
    this.floatingText.dispose();

    // Dispose audio
    this.audio.dispose();

    // Dispose memory manager (disposes all tracked resources)
    this.memory.disposeAll();

    // Dispose renderer and composer
    if (this.renderer) {
      this.renderer.dispose();
    }

    console.log('Space Invaders game disposed successfully');
  }

  public start(): void {
    this.engine.start();
  }

  public stop(): void {
    this.engine.stop();
  }
}

// Initialize game when DOM is ready
window.addEventListener('DOMContentLoaded', () => {
  const game = new SpaceInvadersGame();

  // Expose to window for debugging (optional)
  (window as any).spaceInvadersGame = game;

  // Start the game loop
  game.start();

  // Handle page unload
  window.addEventListener('beforeunload', () => {
    game.dispose();
  });
});

export default SpaceInvadersGame;

